export const GDPR_HEADERS = { "X-GDPR-Consent": "demo" } as const;

// ─── Narrowed frontend types (OpenAPI pages are loosely typed objects) ────

export interface PageResult {
  readonly page: number;
  readonly text: string;
  readonly confidence: number | null;
}

export type OCRPage = PageResult;

export interface TranslatedPage {
  readonly page: number;
  readonly text: string;
  readonly sections?: readonly TranslationSection[];
  readonly status?: "translated" | "partial" | "failed";
}

export interface TranslationSection {
  readonly index: number;
  readonly source_text: string;
  readonly translated_text: string;
  readonly status?: "translated" | "failed";
  readonly attempts?: number;
  readonly error_code?: "TRANSLATION_SECTION_FAILED" | null;
}

export type UploadResponse = Omit<DocumentUploadResponse, "pages"> & {
  readonly pages: readonly OCRPage[];
};

export type TranslateRequest = TranslationRequest;
export type TranslateResponse = Omit<GeneratedTranslationResponse, "translated_pages"> & {
  readonly translated_pages?: readonly TranslatedPage[];
  readonly quality_report?: TranslationQualityReport | null;
};

type DeepReadonly<T> =
  T extends ReadonlyArray<infer Item>
    ? ReadonlyArray<DeepReadonly<Item>>
    : T extends object
      ? { readonly [Key in keyof T]: DeepReadonly<T[Key]> }
      : T;

export type PdfReferenceTranslationResponse = DeepReadonly<PdfReferenceTranslationResult>;

export type PdfReferenceErrorCode =
  | "INVALID_PDF"
  | "FILE_TOO_LARGE"
  | "PAGE_LIMIT_EXCEEDED"
  | "PASSWORD_REQUIRED"
  | "UNSUPPORTED_LANGUAGE"
  | "INVALID_LANGUAGE_PAIR"
  | "AZURE_ANALYSIS_FAILED"
  | "BABELDOC_TRANSLATION_FAILED"
  | "TRANSLATION_QUALITY_FAILED"
  | "PROCESSING_TIMEOUT"
  | "SERVICE_UNAVAILABLE";

export class PdfReferenceApiError extends Error {
  readonly code: PdfReferenceErrorCode | "UNKNOWN";
  readonly retryable: boolean;

  constructor(code: PdfReferenceErrorCode | "UNKNOWN", message: string, retryable = false) {
    super(message);
    this.name = "PdfReferenceApiError";
    this.code = code;
    this.retryable = retryable;
  }
}

export type HealthStatus = ReadinessHealthStatus;
export type PipelineStatus = ApiPipelineStatus;

