export type ExchangeApiErrorCode =
  | "matrix_authentication_required"
  | "matrix_exchange_disabled"
  | "matrix_room_creation_failed"
  | "matrix_room_forbidden"
  | "matrix_invitation_failed"
  | "matrix_invitation_forbidden"
  | "matrix_participant_not_found"
  | "matrix_rate_limited"
  | "matrix_send_failed"
  | "matrix_events_failed"
  | "matrix_upstream_error"
  | "matrix_configuration_error"
  | "matrix_timeout"
  | "unknown";

export class ExchangeApiError extends Error {
  readonly status: number;
  readonly code: ExchangeApiErrorCode;
  readonly retryAfterMs: number | null;

  constructor(status: number, code: ExchangeApiErrorCode, message: string, retryAfterMs: number | null = null) {
    super(message);
    this.name = "ExchangeApiError";
    this.status = status;
    this.code = code;
    this.retryAfterMs = retryAfterMs;
  }
}

/** Static offline payload shape — not part of the OpenAPI spec */
export interface DemoFallbackData {
  readonly fallbackMode: boolean;
  readonly upload?: UploadResponse;
  readonly translate?: TranslateResponse;
  readonly search?: readonly SearchSSEEvent[];
}

function mergeHeaders(headers?: Record<string, string>): Record<string, string> {
  return { ...GDPR_HEADERS, ...headers };
}

function assertOk<T>(result: { data?: T; error?: unknown; response: Response }, label: string): T {
  if (result.error || !result.response.ok || result.data === undefined) {
    const body =
      result.error !== undefined ? JSON.stringify(result.error) : `HTTP ${result.response.status}`;
    throw new Error(`${label} (${result.response.status}): ${body}`);
  }
  return result.data;
}

export async function uploadDocument(
  file: File,
  targetLang: string,
  headers?: Record<string, string>
): Promise<UploadResponse> {
  const validTargetLanguage = targetLang === "en" || targetLang === "fr" ? targetLang : "de";
  const result = await uploadDocumentApiV1DocumentsPost({
    body: {
      file: file as unknown as string,
      target_lang: validTargetLanguage,
    },
    headers: mergeHeaders(headers),
  });
  return assertOk(result, "Upload failed") as unknown as UploadResponse;
}

