export async function translatePdfReference(
  file: File,
  sourceLanguage: string,
  targetLanguage: string,
  expectedPageCount: number,
  headers?: Record<string, string>,
  signal?: AbortSignal
): Promise<PdfReferenceTranslationResponse> {
  const result = await translatePdfReferenceDocumentApiV1TranslatePdfReferencePost({
    body: {
      file: file as unknown as string,
      source_language: sourceLanguage,
      target_language: targetLanguage,
      expected_page_count: expectedPageCount,
    },
    signal,
    headers: mergeHeaders(headers),
  });
  if (result.error || !result.response.ok || result.data === undefined) {
    const error = result.error as
      { detail?: { code?: string; message?: string; retryable?: boolean } } | undefined;
    const detail = error?.detail;
    throw new PdfReferenceApiError(
      (detail?.code as PdfReferenceErrorCode | undefined) ?? "UNKNOWN",
      detail?.message ?? "PDF reference translation failed",
      detail?.retryable ?? false
    );
  }
  return result.data;
}

