export async function createExchangeRoom(
  participants: readonly string[],
  headers?: Record<string, string>
): Promise<CreateExchangeRoomResponse> {
  const result = await createRoomApiV1ExchangeRoomsPost({
    body: { participants: [...participants] },
    headers: {
      ...mergeHeaders(headers),
      "Content-Type": "application/json",
    },
  });
  if (result.error || !result.response.ok || result.data === undefined) {
    const status = result.response.status;
    const error = result.error as
      | {
          readonly detail?:
            | string
              | {
                  readonly code?: string;
                  readonly message?: string;
                  readonly flag?: string;
                  readonly retry_after_ms?: number;
                };
        }
      | undefined;
    const detail = error?.detail;
    const upstreamCode =
      typeof detail === "object" && typeof detail.code === "string" ? detail.code : undefined;
    const featureFlag =
      typeof detail === "object" && typeof detail.flag === "string" ? detail.flag : undefined;
    const retryAfterMs =
      typeof detail === "object" && typeof detail.retry_after_ms === "number"
        ? detail.retry_after_ms
        : null;
    const code: ExchangeApiErrorCode =
      status === 401
        ? "matrix_authentication_required"
        : status === 403 && featureFlag === "ENABLE_MATRIX_EXCHANGE"
          ? "matrix_exchange_disabled"
          : status === 503 && upstreamCode === "matrix_configuration_error"
            ? "matrix_configuration_error"
            : status === 504 && upstreamCode === "matrix_timeout"
              ? "matrix_timeout"
              : upstreamCode === "matrix_room_creation_failed" ||
                  upstreamCode === "matrix_room_forbidden" ||
                  upstreamCode === "matrix_invitation_failed" ||
                  upstreamCode === "matrix_invitation_forbidden" ||
                  upstreamCode === "matrix_participant_not_found" ||
                  upstreamCode === "matrix_rate_limited" ||
                  upstreamCode === "matrix_upstream_error"
                ? (upstreamCode as ExchangeApiErrorCode)
                : "unknown";
    const message =
      typeof detail === "object" && typeof detail.message === "string"
        ? detail.message
        : typeof detail === "string"
          ? detail
          : "Room creation failed";
    throw new ExchangeApiError(status, code, message, retryAfterMs);
  }
  const data = result.data;
  if (typeof data.room_id !== "string" || !data.room_id) {
    throw new Error("Room creation failed: response did not include a room ID");
  }
  return { room_id: data.room_id };
}

