/**
 * SSE streaming search — returns an EventSource connected to the search stream.
 * Caller must attach `result`, `done`, and `error` event listeners.
 *
 * NOTE: useSearchSSE.ts creates its own EventSource directly (with the
 * gdpr_consent query param) rather than using this helper, because
 * EventSource cannot set custom headers. This function is kept for
 * consumers that need a typed stream factory.
 */
export function searchStream(
  query: string,
  gdprConsent: string = "demo",
  headers?: Record<string, string>
): EventSource {
  const params = new URLSearchParams({ q: query, gdpr_consent: gdprConsent });
  const url = `${API_BASE}/api/v1/search/?${params.toString()}`;
  void headers;
  return new EventSource(url);
}

export async function checkHealth(headers?: Record<string, string>): Promise<LivenessStatus> {
  const result = await healthCheckApiV1HealthGet({
    headers: { ...headers },
    signal: AbortSignal.timeout(15000), // 15s for cold starts (was 10s)
  });
  if (result.error || !result.response.ok) {
    throw new Error(`Health check failed (${result.response.status})`);
  }
  return result.data ?? { status: "ok", version: "unknown", sprint: 0 };
}

export async function checkReadiness(
  headers?: Record<string, string>
): Promise<ReadinessHealthStatus> {
  const result = await readinessCheckApiV1HealthReadyGet({
    headers: { ...headers },
    signal: AbortSignal.timeout(10000),
  });
  if (result.error || !result.response.ok) {
    throw new Error(`Readiness check failed (${result.response.status})`);
  }
  return assertOk(result, "Readiness check failed");
}

